const ELEMENT_PROP_KEYS = new Set(["theme","unit","label","value","hop","rest","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  unit: "s",
  label: "scene refresh after a prop change",
  value: 0.0000342,
  hop: 7,
  rest: 12,
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  speed: 1,
};

type PointHopElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PointHopBase>;

const PointHopInner = forwardRef<
  HTMLDivElement,
  PointHopElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PointHop>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PointHopBase
          {...(componentProps as unknown as ComponentProps<typeof PointHopBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PointHop = Interactive.withSchema({
  Component: PointHopInner,
  componentName: "<PointHop>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
